      "when": "आज और आने वाले दिनों में",
      "steps": [
        "पड़ोसियों को जागरूक करें",
        "कचरा जलाने की सूचना दें",
        "सुरक्षित निपटान के तरीके अपनाएं"
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "respiratory",
      "note": "सांस संबंधी समस्याओं वाले सदस्यों के लिए घर के अंदर रहना और इनडोर एयर क्वालिटी बनाए रखना अनिवार्य है।"
    },
    {
      "group": "child",
      "note": "बच्चे के लिए आज बाहर जाना सुरक्षित नहीं है, उसे घर के अंदर ही खेलने के लिए प्रोत्साहित करें।"
    }
  ],
  "tradeoffs": [
    "खिड़कियां बंद रखने से घर में CO2 बढ़ सकती है; इसे संतुलित करने के लिए सुरक्षित समय पर वेंटिलेशन करें।"
  ]
}

